using System;
using System.Collections.Generic;
using System.Linq;

// The shape of Part 1, cut down to show how the pieces connect.
public abstract class Unit
{
    public string Name { get; }
    public int Health { get; private set; }
    public event EventHandler Died;
    protected Unit(string name, int hp) { Name = name; Health = hp; }
    public abstract int Attack { get; }
    public void TakeDamage(int amount)
    {
        if (Health == 0) return;
        Health = Math.Max(0, Health - amount);
        if (Health == 0) Died?.Invoke(this, EventArgs.Empty);
    }
}

public class Grunt : Unit
{
    public Grunt(string name) : base(name, 20) { }
    public override int Attack => 4;
}

class Program
{
    static void Main()
    {
        var wave = new List<Unit> { new Grunt("Grunt 1"), new Grunt("Grunt 2") };
        int alive = wave.Count;
        foreach (var u in wave)
            u.Died += (s, e) => { alive--; Console.WriteLine($"{((Unit)s).Name} down, {alive} left"); if (alive == 0) Console.WriteLine("Wave cleared!"); };

        foreach (var u in wave) u.TakeDamage(25);
        Console.WriteLine($"attack left: {wave.Where(u => u.Health > 0).Sum(u => u.Attack)}");
    }
}

