using System;
using System.Collections.Generic;
using System.Linq;

public interface IDamageable
{
    int Health { get; }
    bool IsDead { get; }
    void TakeDamage(int amount);
}

public abstract class Unit : IDamageable
{
    public string Name { get; }
    public int MaxHealth { get; }
    public int Health { get; private set; }
    public bool IsDead => Health == 0;

    public event EventHandler<int> Damaged;   // how much health was really lost
    public event EventHandler Died;

    protected Unit(string name, int maxHealth)
    {
        if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("A unit needs a name.");
        if (maxHealth <= 0) throw new ArgumentOutOfRangeException(nameof(maxHealth));
        Name = name;
        MaxHealth = Health = maxHealth;
    }

    public abstract int Attack { get; }
    public virtual int Armor => 0;

    public void TakeDamage(int amount)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        if (IsDead) return;
        int taken = Math.Min(Health, Math.Max(0, amount - Armor));
        if (taken == 0) return;
        Health -= taken;
        Damaged?.Invoke(this, taken);
        if (IsDead) Died?.Invoke(this, EventArgs.Empty);
    }

    public override string ToString() => $"{Name} {Health}/{MaxHealth}";
}

public class Soldier : Unit
{
    public Soldier(string name) : base(name, 50) { }
    public override int Attack => 8;
    public override int Armor => 2;
}

public class Archer : Unit
{
    public Archer(string name) : base(name, 30) { }
    public override int Attack => 12;
}

public sealed class Knight : Unit
{
    public Knight(string name) : base(name, 80) { }
    public override int Attack => 10;
    public override int Armor => 5;
}

public class Squad<T> where T : Unit
{
    private readonly List<T> members = new();

    public int Count => members.Count;

    public void Add(T unit)
    {
        if (unit == null) throw new ArgumentNullException(nameof(unit));
        members.Add(unit);
    }

    public List<T> Alive => members.Where(u => !u.IsDead).ToList();

    public int TotalAttack => Alive.Sum(u => u.Attack);

    public T Strongest => Alive.OrderByDescending(u => u.Health).ThenBy(u => u.Name).FirstOrDefault();

    public string Report()
    {
        var alive = Alive.OrderBy(u => u.Name).ToList();
        return alive.Count == 0 ? "(all down)" : string.Join(", ", alive);
    }
}

