public class WaveSpawner
{
    public int Wave { get; private set; }
    public int Kills { get; private set; }
    public Squad<Unit> Enemies { get; private set; }

    public event EventHandler<int> WaveStarted;
    public event EventHandler<int> WaveCleared;

    // The plan is a pure function: easy to test on its own.
    public static List<string> PlanWave(int wave)
    {
        if (wave < 1) throw new ArgumentOutOfRangeException(nameof(wave));
        var names = new List<string>();
        for (int i = 1; i <= wave + 1; i++) names.Add($"Grunt {i}");
        if (wave % 3 == 0) names[names.Count - 1] = "Captain";
        return names;
    }

    public Squad<Unit> SpawnNext()
    {
        if (Enemies != null && Enemies.Alive.Count > 0) throw new InvalidOperationException("Clear the current wave first.");
        Wave++;
        var squad = new Squad<Unit>();
        foreach (string name in PlanWave(Wave))
        {
            Unit u = name == "Captain" ? new Knight(name) : new Soldier(name);
            u.Died += OnEnemyDied;          // the spawner listens; the units don't know about it
            squad.Add(u);
        }
        Enemies = squad;
        WaveStarted?.Invoke(this, Wave);
        return squad;
    }

    private void OnEnemyDied(object sender, EventArgs e)
    {
        Kills++;
        if (Enemies.Alive.Count == 0) WaveCleared?.Invoke(this, Wave);
    }

    public string Summary()
    {
        if (Enemies == null) return "No wave yet";
        var alive = Enemies.Alive;
        return $"Wave {Wave}: {alive.Count}/{Enemies.Count} alive, {alive.Sum(u => u.Health)} HP left";
    }
}

