using System;
using System.Collections.Generic;
using System.Linq;

// The code under test (it is correct): don't change it.
public static class Spawner
{
    public static List<string> PlanWave(int wave)
    {
        if (wave < 1) throw new ArgumentOutOfRangeException(nameof(wave));
        var names = new List<string>();
        for (int i = 1; i <= wave + 1; i++) names.Add($"Grunt {i}");
        if (wave % 3 == 0) names[names.Count - 1] = "Captain";
        return names;
    }
}

public static class SpawnerChecks
{
    public static bool AllPass(Func<int, List<string>> planWave)
    {
        try
        {
            // normal waves: exact names, in order
            if (!Same(planWave(1), "Grunt 1", "Grunt 2")) return false;
            if (!Same(planWave(2), "Grunt 1", "Grunt 2", "Grunt 3")) return false;
            // every third wave ends with the Captain
            if (!Same(planWave(3), "Grunt 1", "Grunt 2", "Grunt 3", "Captain")) return false;
            var six = planWave(6);
            if (six.Count != 7 || six[6] != "Captain" || six[0] != "Grunt 1") return false;
            // and other waves have none
            if (planWave(4).Contains("Captain") || planWave(5).Contains("Captain")) return false;
            // bad input is refused
            if (!Throws(() => planWave(0))) return false;
            if (!Throws(() => planWave(-2))) return false;
            return true;
        }
        catch (Exception)
        {
            return false;   // it crashed where it should have answered
        }
    }

    private static bool Same(List<string> got, params string[] want) => got != null && got.SequenceEqual(want);

    private static bool Throws(Action action)
    {
        try { action(); return false; }
        catch (ArgumentOutOfRangeException) { return true; }
        catch (Exception) { return false; }
    }
}
